import json,sys
from pathlib import Path
p=Path(sys.argv[1]); src=Path('gobreaker.go').read_text().splitlines()
states=['StateClosed','StateOpen','StateHalfOpen','StateHalfOpenSaturated']
events=[e['id'] for e in json.loads((p/'catalogue-fields.json').read_text())['events']]
cells=[]
for state in states:
 c,o,h,s=[state==i for i in states]
 def put(disposition, line, note='',q=None,target=None,crash=False):
  fragment=src[line-1].strip()
  if '|' in fragment: fragment=max(fragment.split('|'),key=len).strip()
  r=dict(state=state,event=e,disposition=disposition,note=note,citation=dict(file='gobreaker.go',line=line,fragment=fragment))
  if q:r['q']=f'Q-{q:02}'
  if target:r['target']=target
  if crash:r['crash']=True
  cells.append(r)
 def admission():
  if o: put('reject',284,'While unexpired. Once expired reconcile before evaluating the refreshed half-open admission budget.')
  elif s: put('reject',286,'Budget includes completed as well as pending admissions in this generation.')
  elif h: put('transition',289,'On final slot, admit and saturate. Below the final slot, admit and stay. No caller identity is checked.',target=states[3])
  else: put('handle',289,'Reconcile expired interval and count admission. Execute invokes request outside lock; Allow returns a report function.')
 def completion():
  if o: put('ignore (documented)',299,'Discard stale accounting after reconciliation, which can itself enter half-open. No current report originated in open.')
  elif c: put('transition',327,'Current failure and true trip policy open the breaker. Success and false policy stay; stale accounting is discarded.',target=states[1])
  else: put('transition',330,'Current failure opens. Current success closes when consecutive successes reach limit, otherwise stays. Stale accounting is discarded.',target=states[1])
 for e in events:
  if e in ('Execute','Allow','UV-02','UV-03','UV-04','UV-05','UV-06'): admission()
  elif e in ('Report','RequestReturn','Classify','UV-11','UV-12','UV-14'): completion()
  elif e in ('StateRead','ReconcileTime','UV-19','UV-08'):
   if o: put('transition',342,'First expiry-check after strict deadline enters half-open. Unexpired check stays. Counts and Name samples leave stored state as is.',target=states[2])
   elif c: put('handle',338,'Expired interval reconciles on State, admission or completion. No read or a pure snapshot leaves stored counts as is.')
   else: put('handle',345,'No half-open expiry or periodic reset.')
  elif e=='CountsRead':put('handle',220,'Return stored snapshot without checking time.')
  elif e=='NameRead':put('handle',202,'Return configured name.')
  elif e=='TripPolicy':
   if c: put('transition',327,'A true result for current failure opens, false stays.',target=states[1])
   else: put('UNSPECIFIED',326,'There is no public injection seam for an independent trip-policy result in this mode. An earlier policy is serialized by the mutex.',q=13)
  elif e=='Notify':put('handle',359,'During entry from another mode, callback observes supplied transition arguments. Callback runs under the lock after generation reset.')
  elif e=='UV-01':put('UNSPECIFIED',229,'An omitted call provides no signal; active work and registration have no teardown entry point.',q=6)
  elif e=='UV-07':put('handle',242,'On admission nil request panics. An unexpired or saturated admission rejects first. Wrong live receiver is used as selected; see Q-08.',q=8,crash=True)
  elif e=='UV-09':put('UNSPECIFIED',271,'No completion is synthesized. An unmatched admission remains counted until generation reset; saturated half-open has no timer.',q=6)
  elif e=='UV-10':put('ignore (documented)',299,'Discard stale accounting after lazily reconciling time; caller result or policy still runs outside that guard.')
  elif e=='UV-13':put('UNSPECIFIED',271,'Manual report requires possession of returned closure; no independent policy delivery seam. Nil callback invocation is a caller panic.',q=13)
  elif e=='UV-15':put('UNSPECIFIED',242,'Work may stall while other callers run. No deadline, interruption or synthetic reporting at this seam.',q=6)
  elif e=='UV-16':put('handle',238,'Execute accounts a recoverable request or classifier panic as failure, then rethrows if accounting returns. Stalled calls have no timeout.',q=10,crash=True)
  elif e=='UV-17':put('handle',359,'A custom locking callback can panic or stall. Trip policy uses the same locked pattern on closed failure; synchronous reentry blocks.',q=9,crash=True)
  elif e=='UV-18':put('UNSPECIFIED',359,'Notification side effect has no explicit acknowledgment or compensation.',q=12)
